#include "watch.h"
#include <chrono>
#include <map>
#include <memory>
#include <mutex>

/*
 * Watchpoints (--watch; docs/LINUX.md "Watchpoints"): hardware data breakpoints, the only way to see a process touch
 * its own memory at an address. Every 100 ms the watch thread resolves each watch in every tracked process (again when
 * msmon's image list of it, ImagesPe, has a new scan), opens a breakpoint (perf_event_open PERF_TYPE_BREAKPOINT, with
 * bpf/watch.bpf.c's mm_watch_hit attached) on each of its threads that has none yet, and closes those of threads,
 * processes and addresses that are gone; every second it writes what the kernel counted as one record per (thread, ip,
 * watch, second). A breakpoint the kernel reports past MM_WATCH_CAP hits in a second is closed at once and not
 * reopened on that thread. Logging only: a data breakpoint traps after the access, so nothing is refused. Without
 * --watch none of this is loaded or run.
 */

namespace {

std::vector<WatchSpec> gSpecs;

}  // namespace

bool LinuxSessionWatch(const std::wstring& spec, std::wstring& error)
{
    error = LinuxWide(WatchAdd(gSpecs, LinuxNarrow(spec)));
    return error.empty();
}

bool WatchWanted()
{
    return !gSpecs.empty();
}

#ifndef MSMON_BPF
int WatchOpen(std::wstring& detail)
{
    detail = L"agent built without BPF (no clang/libbpf at build time): the kernel counts a watch's hits";
    return ENOSYS;
}
void WatchRun(LinuxSession&) {}
void WatchFlush(LinuxSession&) {}
void WatchClose() {}
#else
#include <bpf/bpf.h>
#include <bpf/libbpf.h>
#include <dirent.h>
#include <linux/hw_breakpoint.h>
#include <linux/perf_event.h>
#include <sys/resource.h>
#include <sys/syscall.h>
#include <sys/user.h>
#include <unistd.h>
#include <algorithm>
#include <climits>
#include <cstddef>
#include "watch_bpf_object.h"   /* kWatchBpfObject[], generated by build.sh */

static_assert(offsetof(struct user, u_debugreg) == MM_WATCH_DR0, "watch.bpf.c's PTRACE_POKEUSR offset of DR0");
static_assert(sizeof(mm_watch_key) == 32 && sizeof(mm_watch_hit) == 40, "watch_bpf.h layouts");

namespace {

constexpr auto kTick = std::chrono::milliseconds(100);   /* a thread started later is watched within this */

struct Process {
    uint64_t start = 0;
    bool resolved = false;
    std::shared_ptr<const PeRanges> images;               /* the scan the addresses were resolved against */
    std::vector<uint64_t> addresses;                      /* per watch; 0: not watched in this process */
    std::map<std::pair<DWORD, size_t>, bpf_link*> links;  /* (thread, watch); nullptr: could not be opened, not retried */
};

struct State {
    std::mutex mutex;
    bpf_object* object = nullptr;
    bpf_program* hit = nullptr;
    bpf_link* ptrace = nullptr;
    ring_buffer* over = nullptr;     /* watch_over: breakpoints past MM_WATCH_CAP hits in a second */
    std::vector<mm_watch_key> past;  /* what the last poll of it read (the watch thread's alone) */
    int hits = -1;
    int lost = -1;
    bool stopped = false;
    std::map<DWORD, Process> processes;   /* every tracked process */
} gWatch;

/* A CLOCK_BOOTTIME stamp as FILETIME on the realtime clock (as bpf.cpp's). */
uint64_t BootToFileTime(uint64_t bootNs)
{
    timespec boot{}, real{};
    clock_gettime(CLOCK_BOOTTIME, &boot);
    clock_gettime(CLOCK_REALTIME, &real);
    const int64_t bootNow = static_cast<int64_t>(boot.tv_sec) * 1000000000ll + boot.tv_nsec;
    const int64_t realNow = static_cast<int64_t>(real.tv_sec) * 1000000000ll + real.tv_nsec;
    return MSMON_UNIX_EPOCH_AS_FILETIME + static_cast<uint64_t>((realNow - (bootNow - static_cast<int64_t>(bootNs))) / 100);
}

/* Closes a process's breakpoints of one watch (SIZE_MAX: all); the next tick opens them again where still wanted. */
void Close(Process& process, size_t index = SIZE_MAX)
{
    for (auto it = process.links.begin(); it != process.links.end();) {
        if (index != SIZE_MAX && it->first.second != index) {
            ++it;
            continue;
        }
        if (it->second != nullptr) bpf_link__destroy(it->second);
        it = process.links.erase(it);
    }
}

/* Watch Index's breakpoint at Address on thread Tid with mm_watch_hit attached (the index its cookie), or nullptr and
 * errno. The link owns the event's fd. */
bpf_link* Breakpoint(DWORD tid, size_t index, uint64_t address)
{
    perf_event_attr attr{};
    attr.type = PERF_TYPE_BREAKPOINT;
    attr.size = sizeof(attr);
    attr.bp_type = gSpecs[index].write ? HW_BREAKPOINT_W : HW_BREAKPOINT_RW;
    attr.bp_addr = address;
    attr.bp_len = gSpecs[index].length;   /* HW_BREAKPOINT_LEN_N is N */
    attr.sample_period = 1;
    attr.sample_type = PERF_SAMPLE_IP | PERF_SAMPLE_TID | PERF_SAMPLE_ADDR;
    attr.disabled = 1;         /* libbpf enables it once mm_watch_hit is attached, so no hit goes uncounted */
    attr.exclude_kernel = 1;   /* the thread's own instructions, not the kernel's copies for its system calls */
    const int fd = static_cast<int>(syscall(SYS_perf_event_open, &attr, static_cast<pid_t>(tid), -1, -1, PERF_FLAG_FD_CLOEXEC));
    if (fd < 0) return nullptr;
    bpf_perf_event_opts options{};
    options.sz = sizeof(options);
    options.bpf_cookie = index;
    bpf_link* link = bpf_program__attach_perf_event_opts(gWatch.hit, fd, &options);
    if (link == nullptr) {
        const int error = errno;
        close(fd);
        errno = error;
    }
    return link;
}

/* The process's threads, sorted. */
std::vector<DWORD> Threads(DWORD pid)
{
    std::vector<DWORD> tids;
    DIR* directory = opendir(("/proc/" + std::to_string(pid) + "/task").c_str());
    if (directory == nullptr) return tids;
    while (const dirent* entry = readdir(directory)) {
        if (entry->d_name[0] != '.') tids.push_back(static_cast<DWORD>(std::strtoul(entry->d_name, nullptr, 10)));
    }
    closedir(directory);
    std::sort(tids.begin(), tids.end());
    return tids;
}

/* Opens the breakpoints a process's threads lack and closes those of its threads that are gone. */
void Follow(LinuxSession& session, DWORD pid, Process& process)
{
    if (std::all_of(process.addresses.begin(), process.addresses.end(), [](uint64_t address) { return address == 0; })) return;
    const std::vector<DWORD> tids = Threads(pid);
    for (auto it = process.links.begin(); it != process.links.end();) {
        if (std::binary_search(tids.begin(), tids.end(), it->first.first)) {
            ++it;
            continue;
        }
        if (it->second != nullptr) bpf_link__destroy(it->second);
        it = process.links.erase(it);
    }
    for (DWORD tid : tids) {
        for (size_t index = 0; index < gSpecs.size(); index++) {
            const uint64_t address = process.addresses[index];
            if (address == 0 || process.links.count({tid, index}) != 0) continue;
            bpf_link* link = Breakpoint(tid, index, address);
            const int error = errno;
            if (link == nullptr && error == ESRCH) continue;   /* the thread ended */
            process.links[{tid, index}] = link;
            if (link != nullptr) continue;
            LinuxRecord record = WatchOpenFailed(gSpecs[index], pid, tid, address, error);
            record.start = process.start;
            session.Write(record);
        }
    }
}

/* Writes and deletes the keys that are due; Only: every key of that process (its threads are gone); All: every key. */
void Drain(LinuxSession& session, DWORD only = 0, bool all = false)
{
    timespec now{};
    clock_gettime(CLOCK_BOOTTIME, &now);
    const uint64_t bootNs = static_cast<uint64_t>(now.tv_sec) * 1000000000ull + static_cast<uint64_t>(now.tv_nsec);
    std::vector<mm_watch_key> due;
    mm_watch_key key{}, next{};
    for (bool first = true; bpf_map_get_next_key(gWatch.hits, first ? nullptr : &key, &next) == 0; first = false) {
        key = next;
        if (all || (only != 0 ? key.tgid == only : WatchDue(key.second, bootNs))) due.push_back(key);
    }
    for (const mm_watch_key& one : due) {
        mm_watch_hit hit{};
        if (bpf_map_lookup_and_delete_elem(gWatch.hits, &one, &hit) != 0) continue;
        /* A debug-register write fails ENOSPC only where something else holds the thread's registers: the watches. */
        const auto process = gWatch.processes.find(one.tgid);
        if (process == gWatch.processes.end()) continue;
        if (one.watch != MM_WATCH_CONFLICT && one.watch >= gSpecs.size()) continue;
        LinuxRecord record = WatchRecord(one.watch == MM_WATCH_CONFLICT ? nullptr : &gSpecs[one.watch], one, hit,
                                         process->second.images.get());
        record.start = process->second.start;
        record.timestamp = BootToFileTime(hit.last_ns);
        session.Write(record);
    }
}

/* watch_over's records (ring_buffer__poll in WatchRun): kept for Throttle. */
int OnOver(void*, void* data, size_t size)
{
    if (size >= sizeof(mm_watch_key)) gWatch.past.push_back(*static_cast<const mm_watch_key*>(data));
    return 0;
}

/* Closes the breakpoints the kernel found past MM_WATCH_CAP hits in a second, each for good on its thread (a nullptr
 * link, which Follow does not reopen), with a watch_throttled record. A key of a breakpoint already closed, or of an
 * address the watch has left, is stale. */
void Throttle(LinuxSession& session)
{
    for (const mm_watch_key& key : gWatch.past) {
        const auto process = gWatch.processes.find(key.tgid);
        if (process == gWatch.processes.end() || key.watch >= gSpecs.size() ||
            process->second.addresses[key.watch] != key.addr)
            continue;
        const auto link = process->second.links.find({key.tid, key.watch});
        if (link == process->second.links.end() || link->second == nullptr) continue;
        bpf_link__destroy(link->second);
        link->second = nullptr;
        LinuxRecord record = WatchThrottled(gSpecs[key.watch], key, process->second.images.get());
        record.start = process->second.start;
        session.Write(record);
    }
    gWatch.past.clear();
}

/* One tick: the tracked processes' watches resolved where their images changed, their threads followed. */
void Tick(LinuxSession& session)
{
    std::map<DWORD, uint64_t> tracked;
    for (const auto& process : session.TrackedProcesses()) tracked.insert(process);
    for (auto it = gWatch.processes.begin(); it != gWatch.processes.end();) {
        const auto found = tracked.find(it->first);
        if (found != tracked.end() && found->second == it->second.start) {
            ++it;
            continue;
        }
        Close(it->second);
        Drain(session, it->first);
        it = gWatch.processes.erase(it);
    }
    for (const auto& [pid, start] : tracked) {
        Process& process = gWatch.processes[pid];
        process.start = start;
        std::shared_ptr<const PeRanges> images = ImagesPe(pid, start);
        if (!process.resolved || images != process.images) {
            process.resolved = true;
            process.images = std::move(images);
            for (const auto& [index, previous] : WatchResolveAll(gSpecs, process.images.get(), process.addresses)) {
                Close(process, index);
                LinuxRecord record = WatchMoved(gSpecs[index], pid, previous, process.addresses[index]);
                record.start = start;
                session.Write(record);
            }
        }
        Follow(session, pid, process);
    }
}

/* Opens and loads the watch object, with mm_watch_ptrace or without it: 0 or the errno. */
int Load(bool ptrace)
{
    gWatch.object = bpf_object__open_mem(kWatchBpfObject, sizeof(kWatchBpfObject), nullptr);
    if (gWatch.object == nullptr) return errno != 0 ? errno : EINVAL;
    if (!ptrace) bpf_program__set_autoload(bpf_object__find_program_by_name(gWatch.object, "mm_watch_ptrace"), false);
    const int error = -bpf_object__load(gWatch.object);
    if (error != 0) {
        bpf_object__close(gWatch.object);
        gWatch.object = nullptr;
    }
    return error;
}

}  // namespace

/* In LinuxSession::Start, before the watch thread runs. */
int WatchOpen(std::wstring& detail)
{
    /* fexit/arch_ptrace resolves its target at load: a kernel without it (no BTF for arch_ptrace, no fexit) still counts
     * the hits, without the side=program conflicts. */
    int ptraceError = Load(true);
    const int error = ptraceError == 0 ? 0 : Load(false);
    if (error != 0) {
        detail = L"the watch BPF object did not load (needs root and BTF); see stderr";
        return error;
    }
    /* No watch runs without its cap. */
    gWatch.over = ring_buffer__new(bpf_map__fd(bpf_object__find_map_by_name(gWatch.object, "watch_over")), OnOver, nullptr, nullptr);
    if (gWatch.over == nullptr) {
        const int ringError = errno != 0 ? errno : EINVAL;
        bpf_object__close(gWatch.object);
        gWatch.object = nullptr;
        detail = L"the watch_over ring buffer did not open";
        return ringError;
    }
    gWatch.hit = bpf_object__find_program_by_name(gWatch.object, "mm_watch_hit");
    gWatch.hits = bpf_map__fd(bpf_object__find_map_by_name(gWatch.object, "watch_hits"));
    gWatch.lost = bpf_map__fd(bpf_object__find_map_by_name(gWatch.object, "watch_lost"));
    if (ptraceError == 0) {
        gWatch.ptrace = bpf_program__attach(bpf_object__find_program_by_name(gWatch.object, "mm_watch_ptrace"));
        if (gWatch.ptrace == nullptr) ptraceError = errno;
    }
    /* Each breakpoint is two fds (its event and its link) per thread and watch, so the fd limit goes to its hard maximum. */
    rlimit files{};
    if (getrlimit(RLIMIT_NOFILE, &files) == 0 && files.rlim_cur < files.rlim_max) {
        files.rlim_cur = files.rlim_max;
        setrlimit(RLIMIT_NOFILE, &files);
    }
    gWatch.stopped = false;
    detail = L"watches=";
    for (size_t index = 0; index < gSpecs.size(); index++) detail += (index ? L"," : L"") + LinuxWide(gSpecs[index].text);
    detail += L";keys=" + std::to_wstring(MM_WATCH_KEYS) + L";thread_rescan_ms=" + std::to_wstring(kTick.count()) +
              L";hit_cap=" + std::to_wstring(MM_WATCH_CAP) +
              L";ptrace_conflicts=" + (ptraceError == 0 ? std::wstring(L"on") : L"off:errno=" + std::to_wstring(ptraceError));
    return 0;
}

void WatchRun(LinuxSession& session)
{
    auto next = std::chrono::steady_clock::now() + kTick;
    for (unsigned tick = 1; !session.Stopping();) {
        /* Waits for the next tick, or less: a breakpoint past its cap is closed as soon as the kernel reports it. */
        const auto wait = std::chrono::ceil<std::chrono::milliseconds>(next - std::chrono::steady_clock::now());
        if (wait.count() > 0) ring_buffer__poll(gWatch.over, static_cast<int>(wait.count()));
        std::lock_guard<std::mutex> lock(gWatch.mutex);
        if (gWatch.stopped || gWatch.object == nullptr) return;
        Throttle(session);
        if (std::chrono::steady_clock::now() < next) continue;
        next = std::chrono::steady_clock::now() + kTick;
        Tick(session);
        if (tick++ % 10 == 0) Drain(session);
    }
}

/* Before tracking stops: every breakpoint closed, every count written, and the watch_losses coverage record. */
void WatchFlush(LinuxSession& session)
{
    std::lock_guard<std::mutex> lock(gWatch.mutex);
    if (gWatch.stopped || gWatch.object == nullptr) return;
    gWatch.stopped = true;
    for (auto& item : gWatch.processes) Close(item.second);
    /* shortcut: a hit on another CPU in the microseconds of the close can miss this drain; drain once more after a
     * tick if a stop must account for every last hit. */
    Drain(session, 0, true);
    gWatch.processes.clear();
    std::vector<uint64_t> values(static_cast<size_t>(std::max(libbpf_num_possible_cpus(), 1)));
    const uint32_t zero = 0;
    uint64_t lost = 0;
    if (bpf_map_lookup_elem(gWatch.lost, &zero, values.data()) == 0) {
        for (uint64_t value : values) lost += value;
    }
    LinuxRecord record;
    record.sensor = MSMON_SENSOR_LINUX_EBPF_MEMORY;
    record.type = MsMonCoverage;
    record.flags = MsMonFlagObserverRecord;
    record.text = L"watch_losses";
    record.value0 = lost;
    record.detail = L"hits_full=" + std::to_wstring(lost);
    session.Write(record);
}

void WatchClose()
{
    std::lock_guard<std::mutex> lock(gWatch.mutex);
    for (auto& item : gWatch.processes) Close(item.second);
    gWatch.processes.clear();
    if (gWatch.ptrace != nullptr) bpf_link__destroy(gWatch.ptrace);
    ring_buffer__free(gWatch.over);
    if (gWatch.object != nullptr) bpf_object__close(gWatch.object);
    gWatch.ptrace = nullptr;
    gWatch.over = nullptr;
    gWatch.object = nullptr;
    gWatch.hit = nullptr;
    gWatch.hits = gWatch.lost = -1;
    gWatch.past.clear();
}
#endif
